**Player ship:**
```js
function createShip() {
  const group = new THREE.Group();

  // fuselage - elongated cone
  const bodyGeo = new THREE.ConeGeometry(0.5, 2.5, 8);
  bodyGeo.rotateX(Math.PI / 2);
  const bodyMat = new THREE.MeshStandardMaterial({ color: 0x44aaff, metalness: 0.7, roughness: 0.3 });
  const body = new THREE.Mesh(bodyGeo, bodyMat);
  group.add(body);

  // cockpit
  const cockpitGeo = new THREE.SphereGeometry(0.3, 8, 8);
  const cockpitMat = new THREE.MeshStandardMaterial({ color: 0x88ddff, metalness: 0.9, roughness: 0.1, emissive: 0x224466 });
  const cockpit = new THREE.Mesh(cockpitGeo, cockpitMat);
  cockpit.position.set(0, 0.3, 0.3);
  group.add(cockpit);

  // wings
  const wingGeo = new THREE.BoxGeometry(2.5, 0.08, 0.8);
  const wingMat = new THREE.MeshStandardMaterial({ color: 0x2266aa, metalness: 0.6, roughness: 0.4 });
  const wing = new THREE.Mesh(wingGeo, wingMat);
  wing.position.set(0, 0, -0.5);
  group.add(wing);

  // wing tips
  const tipGeo = new THREE.BoxGeometry(0.15, 0.3, 0.6);
  const tipMat = new THREE.MeshStandardMaterial({ color: 0xff4444, emissive: 0x881111 });
  const tipL = new THREE.Mesh(tipGeo, tipMat);
  tipL.position.set(-1.25, 0.1, -0.5);
  group.add(tipL);
  const tipR = new THREE.Mesh(tipGeo, tipMat);
  tipR.position.set(1.25, 0.1, -0.5);
  group.add(tipR);

  // engine glow
  const glowGeo = new THREE.SphereGeometry(0.25, 8, 8);
  const glowMat = new THREE.MeshBasicMaterial({ color: 0x00ccff, transparent: true, opacity: 0.8 });
  const glow = new THREE.Mesh(glowGeo, glowMat);
  glow.position.set(0, 0, -1.3);
  group.add(glow);
  group.userData.engineGlow = glow;

  return group;
}
```

**Asteroids:**
```js
function createAsteroidGeometry(radius) {
  const geo = new THREE.IcosahedronGeometry(radius, 1);
  const pos = geo.attributes.position;
  const v = new THREE.Vector3();
  for (let i = 0; i < pos.count; i++) {
    v.fromBufferAttribute(pos, i);
    const noise = 1 + (Math.sin(v.x * 5.3) * Math.cos(v.y * 4.7) * Math.sin(v.z * 6.1)) * 0.35;
    v.multiplyScalar(noise);
    pos.setXYZ(i, v.x, v.y, v.z);
  }
  geo.computeVertexNormals();
  return geo;
}
```

Wait, IcosahedronGeometry in r128 - is it indexed? In r128, IcosahedronGeometry extends PolyhedronGeometry which is non-indexed (each face has its own vertices). So displacing per-vertex would create cracks. I need to hash by position so vertices at the same position get the same displacement.

```js
function hashNoise(x, y, z) {
  const s = Math.sin(x * 12.9898 + y * 78.233 + z * 37.719) * 43758.5453;
  return (s - Math.floor(s)) * 2 - 1;
}

function createAsteroidGeometry(radius) {
  const geo = new THREE.IcosahedronGeometry(radius, 1);
  const pos = geo.attributes.position;
  const v = new THREE.Vector3();
  for (let i = 0; i < pos.count; i++) {
    v.fromBufferAttribute(pos, i);
    const n = hashNoise(Math.round(v.x * 100) / 100, Math.round(v.y * 100) / 100, Math.round(v.z * 100) / 100);
    const scale = 1 + n * 0.35;
    pos.setXYZ(i, v.x * scale, v.y * scale, v.z * scale);
  }
  geo.computeVertexNormals();
  return geo;
}
```

Hmm, rounding to 2 decimal places should work for matching vertices since icosahedron vertices are at exact positions. Actually, let me use a different approach - use a Map keyed by position string:

```js
function createAsteroidGeometry(radius) {
  const geo = new THREE.IcosahedronGeometry(radius, 1);
  const pos = geo.attributes.position;
  const cache = new Map();
  const v = new THREE.Vector3();
  for (let i = 0; i < pos.count; i++) {
    v.fromBufferAttribute(pos, i);
    const key = v.x.toFixed(3) + ',' + v.y.toFixed(3) + ',' + v.z.toFixed(3);
    if (!cache.has(key)) {
      cache.set(key, 1 + (Math.random() * 0.5 + Math.random() * 0.5 - 0.5) * 0.5);
    }
    const scale = cache.get(key);
    pos.setXYZ(i, v.x * scale, v.y * scale, v.z * scale);
  }
  geo.computeVertexNormals();
  return geo;
}
```

This is safer. Using toFixed(3) as key and caching the scale factor.

**Bullets:**
```js
const bullets = [];
const bulletPool = [];
const MAX_BULLETS = 30;

function createBullet() {
  const geo = new THREE.CylinderGeometry(0.05, 0.05, 1.5, 6);
  geo.rotateX(Math.PI / 2);
  const mat = new THREE.MeshBasicMaterial({ color: 0x00ffff });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.visible = false;
  scene.add(mesh);
  return mesh;
}

for (let i = 0; i < MAX_BULLETS; i++) {
  bulletPool.push(createBullet());
}

function fireBullet(origin, direction) {
  const b = bulletPool.find(b => !b.visible);
  if (!b) return;
  b.visible = true;
  b.position.copy(origin);
  b.lookAt(origin.clone().add(direction));
  b.userData.velocity = direction.clone().multiplyScalar(80);
  b.userData.life = 1.5;
  bullets.push(b);
}
```

**Particles:**
I'll use a single Points system with a pool of particles:

```js
const MAX_PARTICLES = 500;
const particleGeo = new THREE.BufferGeometry();
const pPositions = new Float32Array(MAX_PARTICLES * 3);
const pColors = new Float32Array(MAX_PARTICLES * 3);
const pSizes = new Float32Array(MAX_PARTICLES);
particleGeo.setAttribute('position', new THREE.BufferAttribute(pPositions, 3));
particleGeo.setAttribute('color', new THREE.BufferAttribute(pColors, 3));
particleGeo.setAttribute('size', new THREE.BufferAttribute(pSizes, 1));

const particleMat = new THREE.PointsMaterial({
  size: 0.5,
  vertexColors: true,
  blending: THREE.AdditiveBlending,
  transparent: true,
  depthWrite: false
});

const particleSystem = new THREE.Points(particleGeo, particleMat);
scene.add(particleSystem);

const particles = [];
for (let i = 0; i < MAX_PARTICLES; i++) {
  particles.push({ alive: false, pos: new THREE.Vector3(), vel: new THREE.Vector3(), life: 0, maxLife: 1, color: new THREE.Color() });
}

function spawnParticle(pos, vel, life, color) {
  const p = particles.find(p => !p.alive);
  if (!p) return;
  p.alive = true;
  p.pos.copy(pos);
  p.vel.copy(vel);
  p.life = life;
  p.maxLife = life;
  p.color.set(color);
}

function spawnExplosion(pos, count, color, speed) {
  for (let i = 0; i < count; i++) {
    const vel = new THREE.Vector3(
      (Math.random() - 0.5) * 2,
      (Math.random() - 0.5) * 2,
      (Math.random() - 0.5) * 2
    ).normalize().multiplyScalar(speed * (0.5 + Math.random() * 0.5));
    spawnParticle(pos, vel, 0.5 + Math.random() * 0.5, color);
  }
}
```

Wait, PointsMaterial doesn't support per-particle size in r128 without a custom shader. I'll use a fixed size and just vary color/alpha. Actually, I can fade by moving dead particles far away or setting color to black (with additive blending, black = invisible). That's the trick - with AdditiveBlending, setting color to black makes particles invisible.

So in the update:
```js
for (let i = 0; i < MAX_PARTICLES; i++) {
  const p = particles[i];
  if (p.alive) {
    p.life -= dt;
    if (p.life <= 0) {
      p.alive = false;
      pColors[i*3] = 0; pColors[i*3+1] = 0; pColors[i*3+2] = 0;
    } else {
      p.pos.addScaledVector(p.vel, dt);
      p.vel.multiplyScalar(0.98);
      const t = p.life / p.maxLife;
      pColors[i*3] = p.color.r * t;
      pColors[i*3+1] = p.color.g * t;
      pColors[i*3+2] = p.color.b * t;
    }
    pPositions[i*3] = p.pos.x;
    pPositions[i*3+1] = p.pos.y;
    pPositions[i*3+2] = p.pos.z;
  }
}
particleGeo.attributes.position.needsUpdate = true;
particleGeo.attributes.color.needsUpdate = true;
```

