**Autopilot:**
```js
function autopilotUpdate(dt) {
  // find nearest asteroid
  let nearest = null;
  let nearestDist = Infinity;
  for (const a of asteroids) {
    const d = ship.position.distanceTo(a.mesh.position);
    if (d < nearestDist) { nearestDist = d; nearest = a; }
  }

  let targetAngle;
  if (nearest && nearestDist < 80) {
    const dir = nearest.mesh.position.clone().sub(ship.position);
    targetAngle = Math.atan2(dir.x, dir.z);
  } else {
    // steer to center
    targetAngle = Math.atan2(-ship.position.x, -ship.position.z);
  }

  // boundary check
  const distFromCenter = ship.position.length();
  if (distFromCenter > 120) {
    targetAngle = Math.atan2(-ship.position.x, -ship.position.z);
  }

  // steer toward target angle
  let angleDiff = targetAngle - ship.rotation.y;
  while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
  while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

  ship.rotation.y += THREE.MathUtils.clamp(angleDiff, -2.5 * dt, 2.5 * dt);

  // thrust if roughly aligned
  if (Math.abs(angleDiff) < 0.5) {
    thrustShip(dt);
  }

  // fire if aligned
  if (Math.abs(angleDiff) < 0.15 && nearest && nearestDist < 60) {
    tryFire();
  }
}
```

**Game state:**
```js
let gameState = 'attract'; // 'attract', 'playing', 'gameover'
let score = 0;
let lives = 3;
let wave = 1;
let invulnerable = 0;
let fireCooldown = 0;

function startGame() {
  gameState = 'playing';
  score = 0;
  lives = 3;
  wave = 1;
  clearAsteroids();
  spawnWave();
  ship.position.set(0, 0, 0);
  ship.rotation.set(0, 0, 0);
  ship.visible = true;
  invulnerable = 2;
  updateHUD();
  hideMessage();
}

function gameOver() {
  gameState = 'gameover';
  showMessage('GAME OVER', 'SCORE: ' + score + '<br><br>PRESS ANY KEY');
  AudioSys.gameOver();
}

function nextWave() {
  wave++;
  showMessage('WAVE ' + wave, '');
  setTimeout(() => { if (gameState === 'playing') hideMessage(); }, 1500);
  spawnWave();
  AudioSys.waveClear();
}
```

**Main loop:**
```js
let last = performance.now();
function animate(now) {
  requestAnimationFrame(animate);
  const dt = Math.min((now - last) / 1000, 0.05);
  last = now;

  // check idle for autopilot
  if (gameState === 'playing' && performance.now() - lastInputTime > 3000) {
    autopilot = true;
  }

  if (gameState === 'playing') {
    if (autopilot) {
      autopilotUpdate(dt);
    } else {
      playerUpdate(dt);
    }
  } else if (gameState === 'attract' || gameState === 'gameover') {
    autopilotUpdate(dt);
  }

  updateAsteroids(dt);
  updateBullets(dt);
  updateParticles(dt);
  updateCamera(dt);
  updateHUD();

  renderer.render(scene, camera);
}
```

**Camera:**
```js
function updateCamera(dt) {
  const offset = new THREE.Vector3(0, 3, 8);
  offset.applyQuaternion(ship.quaternion);
  const targetPos = ship.position.clone().add(offset);
  camera.position.lerp(targetPos, 1 - Math.pow(0.001, dt));
  const lookAt = ship.position.clone().add(
    new THREE.Vector3(0, 0, -10).applyQuaternion(ship.quaternion)
  );
  camera.lookAt(lookAt);
}
```

**Player update:**
```js
function playerUpdate(dt) {
  const rotSpeed = 3;
  if (keys['ArrowLeft'] || keys['KeyA']) ship.rotation.y += rotSpeed * dt;
  if (keys['ArrowRight'] || keys['KeyD']) ship.rotation.y -= rotSpeed * dt;

  const thrusting = keys['ArrowUp'] || keys['KeyW'];
  if (thrusting) thrustShip(dt);

  if (keys['Space']) tryFire();

  AudioSys.setEngine(thrusting ? 1 : 0);
}

function thrustShip(dt) {
  const dir = new THREE.Vector3(0, 0, -1).applyQuaternion(ship.quaternion);
  ship.position.addScaledVector(dir, 30 * dt);

  // engine particles
  const exhaustPos = ship.position.clone().add(
    new THREE.Vector3(0, 0, -1.5).applyQuaternion(ship.quaternion)
  );
  const exhaustVel = dir.clone().multiplyScalar(-10);
  spawnParticle(exhaustPos, exhaustVel, 0.3, new THREE.Color(0, 0.5, 1));

  // engine glow pulse
  ship.userData.engineGlow.scale.setScalar(1 + Math.random() * 0.3);
}

function tryFire() {
  if (fireCooldown > 0) return;
  fireCooldown = 0.15;
  const dir = new THREE.Vector3(0, 0, -1).applyQuaternion(ship.quaternion);
  const origin = ship.position.clone().add(dir.clone().multiplyScalar(1.5));
  fireBullet(origin, dir);
  AudioSys.laser();
}
```

**Asteroid management:**
```js
const asteroids = [];
const ASTEROID_SIZES = [
  { radius: 3, score: 20 },
  { radius: 1.5, score: 50 },
  { radius: 0.7, score: 100 }
];

function spawnAsteroid(size, position) {
  const sizeData = ASTEROID_SIZES[size];
  const geo = createAsteroidGeometry(sizeData.radius);
  const mat = new THREE.MeshStandardMaterial({
    color: new THREE.Color(0.4 + Math.random() * 0.2, 0.35 + Math.random() * 0.15, 0.3 + Math.random() * 0.1),
    roughness: 0.9,
    metalness: 0.1,
    flatShading: true
  });
  const mesh = new THREE.Mesh(geo, mat);

  if (!position) {
    // spawn at edge of arena
    const angle = Math.random() * Math.PI * 2;
    const r = 100 + Math.random() * 40;
    position = new THREE.Vector3(Math.cos(angle) * r, (Math.random() - 0.5) * 40, Math.sin(angle) * r);
  }
  mesh.position.copy(position);

  const vel = new THREE.Vector3(
    (Math.random() - 0.5) * 10,
    (Math.random() - 0.5) * 5,
    (Math.random() - 0.5) * 10
  );

  const rotVel = new THREE.Vector3(
    (Math.random() - 0.5) * 2,
    (Math.random() - 0.5) * 2,
    (Math.random() - 0.5) * 2
  );

  scene.add(mesh);
  asteroids.push({ mesh, vel, rotVel, size, radius: sizeData.radius, score: sizeData.score });
}

function spawnWave() {
  const count = 3 + wave;
  for (let i = 0; i < count; i++) {
    spawnAsteroid(0);
  }
}

function destroyAsteroid(index) {
  const a = asteroids[index];
  scene.remove(a.mesh);
  a.mesh.geometry.dispose();
  a.mesh.material.dispose();
  asteroids.splice(index, 1);

  // spawn smaller asteroids
  if (a.size < 2) {
    for (let i = 0; i < 2; i++) {
      spawnAsteroid(a.size + 1, a.mesh.position.clone());
    }
  }

  // explosion
  spawnExplosion(a.mesh.position, 20, new THREE.Color(1, 0.5, 0), 15);
  AudioSys.explosion(a.size);

  score += a.score;
  updateHUD();

  if (asteroids.length === 0 && gameState === 'playing') {
    nextWave();
  }
}
```

**Collision detection:**
```js
function checkCollisions() {
  // bullets vs asteroids
  for (let bi = bullets.length - 1; bi >= 0; bi--) {
    const b = bullets[bi];
    if (!b.visible) continue;
    for (let ai = asteroids.length - 1; ai >= 0; ai--) {
      const a = asteroids[ai];
      if (b.position.distanceTo(a.mesh.position) < a.radius + 0.5) {
        b.visible = false;
        destroyAsteroid(ai);
        break;
      }
    }
  }

  // ship vs asteroids
  if (invulnerable <= 0 && gameState === 'playing') {
    for (let ai = asteroids.length - 1; ai >= 0; ai--) {
      const a = asteroids[ai];
      if (ship.position.distanceTo(a.mesh.position) < a.radius + 1) {
        destroyAsteroid(ai);
        playerHit();
        break;
      }
    }
  }
}

function playerHit() {
  lives--;
  spawnExplosion(ship.position, 40, new THREE.Color(0, 0.8, 1), 20);
  AudioSys.explosion(2);
  updateHUD();

  if (lives <= 0) {
    ship.visible = false;
    gameOver();
  } else {
    invulnerable = 3;
    ship.position.set(0, 0, 0);
    ship.rotation.set(0, 0, 0);
  }
}
```

