// ==================== BULLETS ====================
const bullets = [];
const bulletPool = [];
const MAX_BULLETS = 30;

function initBullets() {
  const geo = new THREE.BoxGeometry(0.1, 0.1, 1.4);
  const mat = new THREE.MeshBasicMaterial({ color: 0x00ffff, blending: THREE.AdditiveBlending, transparent: true, opacity: 0.95, depthWrite: false });
  for (let i = 0; i < MAX_BULLETS; i++) {
    const m = new THREE.Mesh(geo, mat);
    m.visible = false;
    scene.add(m);
    bulletPool.push(m);
  }
}
initBullets();

function fireBullet(origin, dir) {
  const b = bulletPool.find(b => !b.visible);
  if (!b) return;
  b.visible = true;
  b.position.copy(origin);
  b.lookAt(origin.clone().add(dir));
  b.userData.vel = dir.clone().multiplyScalar(85);
  b.userData.life = 1.4;
  bullets.push(b);
}

